import{_ as a,o as r,c as i,am as t}from"./chunks/framework.CO8FpuMG.js";const m=JSON.parse('{"title":"Tutorials Overview","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/overview.md","filePath":"tutorials/overview.md","lastUpdated":null}'),o={name:"tutorials/overview.md"};function n(s,e,l,d,p,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="Tutorials-Overview" tabindex="-1">Tutorials Overview <a class="header-anchor" href="#Tutorials-Overview" aria-label="Permalink to &quot;Tutorials Overview {#Tutorials-Overview}&quot;">​</a></h1><p>Welcome to the EasyHybrid.jl tutorials! This section provides comprehensive guides and examples to help you get started with hybrid modeling—combining process-based models with neural networks.</p><h2 id="Getting-Started" tabindex="-1">Getting Started <a class="header-anchor" href="#Getting-Started" aria-label="Permalink to &quot;Getting Started {#Getting-Started}&quot;">​</a></h2><p>If you&#39;re new to EasyHybrid.jl, we recommend starting with the <a href="./../get_started">Getting Started</a> guide, which walks through building your first hybrid model step by step.</p><h2 id="Tutorial-Topics" tabindex="-1">Tutorial Topics <a class="header-anchor" href="#Tutorial-Topics" aria-label="Permalink to &quot;Tutorial Topics {#Tutorial-Topics}&quot;">​</a></h2><p>The tutorials are grouped into four sections, in the order we recommend reading them.</p><h3 id="Fundamentals" tabindex="-1">Fundamentals <a class="header-anchor" href="#Fundamentals" aria-label="Permalink to &quot;Fundamentals {#Fundamentals}&quot;">​</a></h3><h4 id="Building-Modelsbuilding_models.md" tabindex="-1"><a href="./building_models">Building Models</a> <a class="header-anchor" href="#Building-Modelsbuilding_models.md" aria-label="Permalink to &quot;[Building Models](building_models.md) {#Building-Modelsbuilding_models.md}&quot;">​</a></h4><p>See how different model architectures (linear hybrids, respiration models with Q10, and more) are built with the unified <code>HybridModel</code> struct.</p><p><strong>Best for</strong>: Getting an overview of the model types you can express with EasyHybrid.jl.</p><h4 id="Exponential-Respiration-Modelexponential_res.md" tabindex="-1"><a href="./exponential_res">Exponential Respiration Model</a> <a class="header-anchor" href="#Exponential-Respiration-Modelexponential_res.md" aria-label="Permalink to &quot;[Exponential Respiration Model](exponential_res.md) {#Exponential-Respiration-Modelexponential_res.md}&quot;">​</a></h4><p>Learn to build a hybrid model for soil respiration using an exponential temperature relationship. This tutorial demonstrates:</p><ul><li><p>Creating synthetic data with exponential temperature response</p></li><li><p>Defining a process-based model (<code>Expo_resp_model</code>)</p></li><li><p>Configuring model parameters and constructing hybrid models</p></li><li><p>Training and evaluating your model</p></li></ul><p><strong>Best for</strong>: Understanding the fundamentals of hybrid modeling with a simple, well-documented example.</p><h4 id="Losses-and-LoggingLosslosses.md" tabindex="-1"><a href="./losses">Losses and LoggingLoss</a> <a class="header-anchor" href="#Losses-and-LoggingLosslosses.md" aria-label="Permalink to &quot;[Losses and LoggingLoss](losses.md) {#Losses-and-LoggingLosslosses.md}&quot;">​</a></h4><p>Deep dive into the loss function system in EasyHybrid.jl. Learn about:</p><ul><li><p>Predefined loss functions (MSE, MAE, NSE)</p></li><li><p>Creating custom loss functions</p></li><li><p>Handling missing values and uncertainty</p></li><li><p>Using <code>LoggingLoss</code> for training and evaluation</p></li><li><p>Passing additional arguments and keyword arguments to losses</p></li></ul><p><strong>Best for</strong>: Customizing model training and implementing domain-specific loss functions.</p><h3 id="Training-and-Evaluation" tabindex="-1">Training &amp; Evaluation <a class="header-anchor" href="#Training-and-Evaluation" aria-label="Permalink to &quot;Training &amp; Evaluation {#Training-and-Evaluation}&quot;">​</a></h3><h4 id="Training-Dashboarddashboard.md" tabindex="-1"><a href="./dashboard">Training Dashboard</a> <a class="header-anchor" href="#Training-Dashboarddashboard.md" aria-label="Permalink to &quot;[Training Dashboard](dashboard.md) {#Training-Dashboarddashboard.md}&quot;">​</a></h4><p>Configure the modular training dashboard: choose which plots are rendered during training, how they are arranged, and which ones are saved as animations.</p><p><strong>Best for</strong>: Monitoring training runs and recording them.</p><h4 id="Cross-Validationfolds.md" tabindex="-1"><a href="./folds">Cross-Validation</a> <a class="header-anchor" href="#Cross-Validationfolds.md" aria-label="Permalink to &quot;[Cross-Validation](folds.md) {#Cross-Validationfolds.md}&quot;">​</a></h4><p>Implement k-fold cross-validation to robustly evaluate your hybrid models. Learn how to:</p><ul><li><p>Create and manage data folds</p></li><li><p>Train models across multiple validation splits</p></li><li><p>Parallelize cross-validation training</p></li><li><p>Organize results from multiple model runs</p></li></ul><p><strong>Best for</strong>: Ensuring your model generalizes well and avoiding overfitting.</p><h4 id="Hyperparameter-Tuninghyperparameter_tuning.md" tabindex="-1"><a href="./hyperparameter_tuning">Hyperparameter Tuning</a> <a class="header-anchor" href="#Hyperparameter-Tuninghyperparameter_tuning.md" aria-label="Permalink to &quot;[Hyperparameter Tuning](hyperparameter_tuning.md) {#Hyperparameter-Tuninghyperparameter_tuning.md}&quot;">​</a></h4><p>Optimize your model&#39;s performance using Hyperopt.jl for automated hyperparameter search. This tutorial shows:</p><ul><li><p>Setting up hyperparameter search spaces</p></li><li><p>Using the <code>tune</code> function for optimization</p></li><li><p>Comparing model performance before and after tuning</p></li><li><p>Best practices for hyperparameter selection</p></li></ul><p><strong>Best for</strong>: Finding optimal model configurations and improving performance.</p><h3 id="Sequence-Models" tabindex="-1">Sequence Models <a class="header-anchor" href="#Sequence-Models" aria-label="Permalink to &quot;Sequence Models {#Sequence-Models}&quot;">​</a></h3><h4 id="Sequence-Hybrid-Models-LSTM-and-Transformerexample_synthetic_sequence.md" tabindex="-1"><a href="./example_synthetic_sequence">Sequence Hybrid Models (LSTM &amp; Transformer)</a> <a class="header-anchor" href="#Sequence-Hybrid-Models-LSTM-and-Transformerexample_synthetic_sequence.md" aria-label="Permalink to &quot;[Sequence Hybrid Models (LSTM &amp; Transformer)](example_synthetic_sequence.md) {#Sequence-Hybrid-Models-LSTM-and-Transformerexample_synthetic_sequence.md}&quot;">​</a></h4><p>Explore advanced neural network architectures by building a hybrid model with LSTM (Long Short-Term Memory) networks. This tutorial covers:</p><ul><li><p>Using LSTM networks for sequence modeling</p></li><li><p>Configuring feedforward vs. recurrent architectures</p></li><li><p>Working with sequence data (input/output windows, lead times)</p></li><li><p>Comparing LSTM and standard neural network performance</p></li></ul><p><strong>Best for</strong>: Working with time series data that requires memory of past states.</p><h4 id="Transformer-Mathematics../transformer_math.md" tabindex="-1"><a href="./../transformer_math">Transformer Mathematics</a> <a class="header-anchor" href="#Transformer-Mathematics../transformer_math.md" aria-label="Permalink to &quot;[Transformer Mathematics](../transformer_math.md) {#Transformer-Mathematics../transformer_math.md}&quot;">​</a></h4><p>The tensor operations behind the experimental <code>EasyHybrid.Transformers</code> module, mapped to the source files that implement them.</p><p><strong>Best for</strong>: Understanding or extending the Transformer layers.</p><h4 id="Forecasting-Approaches../forecasting_approaches.md" tabindex="-1"><a href="./../forecasting_approaches">Forecasting Approaches</a> <a class="header-anchor" href="#Forecasting-Approaches../forecasting_approaches.md" aria-label="Permalink to &quot;[Forecasting Approaches](../forecasting_approaches.md) {#Forecasting-Approaches../forecasting_approaches.md}&quot;">​</a></h4><p>Why EasyHybrid uses direct multi-step forecasting for Transformers, and which autoregressive architectures could be added later.</p><p><strong>Best for</strong>: Choosing a forecasting strategy for time-series targets.</p><h3 id="Scaling-and-HPC" tabindex="-1">Scaling &amp; HPC <a class="header-anchor" href="#Scaling-and-HPC" aria-label="Permalink to &quot;Scaling &amp; HPC {#Scaling-and-HPC}&quot;">​</a></h3><h4 id="GPU-Accelerationgpu.md" tabindex="-1"><a href="./gpu">GPU Acceleration</a> <a class="header-anchor" href="#GPU-Accelerationgpu.md" aria-label="Permalink to &quot;[GPU Acceleration](gpu.md) {#GPU-Accelerationgpu.md}&quot;">​</a></h4><p>Install the backend package for your hardware (NVIDIA, AMD, Apple) and train on GPU.</p><p><strong>Best for</strong>: Speeding up training on larger models or datasets.</p><h4 id="Synthetic-Respiration-on-GPUsynthetic_respiration_gpu.md" tabindex="-1"><a href="./synthetic_respiration_gpu">Synthetic Respiration on GPU</a> <a class="header-anchor" href="#Synthetic-Respiration-on-GPUsynthetic_respiration_gpu.md" aria-label="Permalink to &quot;[Synthetic Respiration on GPU](synthetic_respiration_gpu.md) {#Synthetic-Respiration-on-GPUsynthetic_respiration_gpu.md}&quot;">​</a></h4><p>A complete example that trains a Q10 respiration hybrid model on synthetic data on a GPU.</p><p><strong>Best for</strong>: Seeing a full GPU training workflow end to end.</p><h4 id="Slurm-Jobsslurm.md" tabindex="-1"><a href="./slurm">Slurm Jobs</a> <a class="header-anchor" href="#Slurm-Jobsslurm.md" aria-label="Permalink to &quot;[Slurm Jobs](slurm.md) {#Slurm-Jobsslurm.md}&quot;">​</a></h4><p>Run EasyHybrid.jl models on HPC clusters using Slurm job scheduling. This tutorial provides:</p><ul><li><p>Example Slurm batch scripts</p></li><li><p>Configuring Julia for cluster environments</p></li><li><p>Running array jobs for parallel experiments</p></li><li><p>Resource allocation best practices</p></li></ul><p><strong>Best for</strong>: Scaling up training to high-performance computing environments.</p><h2 id="Choosing-the-Right-Tutorial" tabindex="-1">Choosing the Right Tutorial <a class="header-anchor" href="#Choosing-the-Right-Tutorial" aria-label="Permalink to &quot;Choosing the Right Tutorial {#Choosing-the-Right-Tutorial}&quot;">​</a></h2><ul><li><p><strong>New to EasyHybrid?</strong> → Start with <a href="./exponential_res">Exponential Respiration Model</a></p></li><li><p><strong>Working with time series?</strong> → Check out <a href="./example_synthetic_sequence">Sequence Hybrid Models (LSTM &amp; Transformer)</a></p></li><li><p><strong>Need robust evaluation?</strong> → See <a href="./folds">Cross-Validation</a></p></li><li><p><strong>Want to optimize performance?</strong> → Try <a href="./hyperparameter_tuning">Hyperparameter Tuning</a></p></li><li><p><strong>Customizing training?</strong> → Read <a href="./losses">Losses and LoggingLoss</a></p></li><li><p><strong>Training on GPU?</strong> → See <a href="./gpu">GPU Acceleration</a></p></li><li><p><strong>Running on clusters?</strong> → Follow <a href="./slurm">Slurm Jobs</a></p></li></ul><h2 id="Next-Steps" tabindex="-1">Next Steps <a class="header-anchor" href="#Next-Steps" aria-label="Permalink to &quot;Next Steps {#Next-Steps}&quot;">​</a></h2><p>After completing the tutorials, explore the <a href="./../research/overview">Research</a> section to see real-world applications, or dive into the <a href="./../api">API Reference</a> for detailed function documentation.</p>',56)])])}const c=a(o,[["render",n]]);export{m as __pageData,c as default};
